/**
 * Cloudflare Workers entry: the OpenNext-generated Next.js handler, plus a
 * scheduled handler for the hourly cron trigger in wrangler.jsonc. The job
 * calls the app's own /api/cron/recurring with CRON_SECRET, exactly like the
 * other hosts' schedulers (idempotent; safe to repeat).
 */
// Generated by `opennextjs-cloudflare build`; absent until the first build.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as handler } from "../.open-next/worker.js";

interface Env {
  CRON_SECRET?: string;
}

interface Ctx {
  waitUntil(promise: Promise<unknown>): void;
}

type Dispose = (ctx: object) => Promise<void>;

/**
 * Serve the request, then close its database connections once the response
 * body has been fully sent (pages stream, so not before). See src/server/db.ts.
 */
async function fetchAndDispose(request: Request, env: Env, ctx: Ctx): Promise<Response> {
  const dispose = () =>
    (globalThis as { __disposeRequestDb?: Dispose }).__disposeRequestDb?.(ctx) ?? Promise.resolve();
  let response: Response;
  try {
    response = await handler.fetch(request, env, ctx);
  } catch (error) {
    ctx.waitUntil(dispose());
    throw error;
  }
  if (!response.body) {
    ctx.waitUntil(dispose());
    return response;
  }
  const { readable, writable } = new TransformStream();
  ctx.waitUntil(
    response.body
      .pipeTo(writable)
      .catch(() => {}) // the visitor went away mid-response
      .finally(dispose),
  );
  return new Response(readable, response);
}

const worker = {
  fetch: fetchAndDispose,

  async scheduled(_event: unknown, env: Env, ctx: Ctx) {
    if (!env.CRON_SECRET) {
      console.error(JSON.stringify({ level: "error", event: "scheduler.not_configured" }));
      return;
    }
    const request = new Request("https://scheduler.internal/api/cron/recurring", {
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    const response = await fetchAndDispose(request, env, ctx);
    // Read the (small) result to the end: cancelling it while Next.js is still
    // writing would throw "This ReadableStream is closed".
    await response.text();
    const level = response.ok ? "info" : "error";
    console.log(JSON.stringify({ level, event: "scheduler.run", status: response.status }));
  },
};

export default worker;
